const $=s=>document.querySelector(s),main=$('#main');let progress={proposals:{}},progressLoaded=false;let index,portraits={people:{}},portraitsLoaded=false,cache=new Map(),selected=null,viewMonth=null,generation=0,gridGeneration=0;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR');const monthName=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'});const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
async function json(p){const r=await fetch(p,{cache:'no-store'});if(!r.ok)throw Error('Não foi possível carregar os dados.');return r.json()}async function month(m){if(!index.months.some(x=>x.month===m))return null;if(!cache.has(m))cache.set(m,json('data/'+m+'.json').catch(e=>{cache.delete(m);throw e}));return cache.get(m)}
function portrait(a){const initials=(a.name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('');const url=portraits.people?.[a.id]?.photo;return `<span class="portrait"><span class="portrait-initials" aria-hidden="true">${esc(initials)}</span>${url?`<img class="parliament-photo" src="${esc(url)}" alt="Foto oficial de ${esc(a.name)}" loading="lazy" referrerpolicy="no-referrer">`:'<span class="photo-unavailable" role="img" aria-label="Foto oficial não disponível"></span>'}</span>`}
function bindPortraitErrors(){document.querySelectorAll('.parliament-photo').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.parentElement.setAttribute('aria-label','Foto oficial indisponível; exibindo iniciais')}))}
function heading(k,t,p){return `<div class="topline"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p class="intro">${p}</p></div><div class="edition">BRASÍLIA, BRASIL &nbsp; ↗</div></div>`}function closeMenu(){document.body.classList.remove('mobile-open');$('#menu').setAttribute('aria-expanded',String(innerWidth>700&&!document.body.classList.contains('closed')))}$('#menu').onclick=()=>{document.body.classList.toggle(innerWidth<=700?'mobile-open':'closed');$('#menu').setAttribute('aria-expanded',String(innerWidth<=700?document.body.classList.contains('mobile-open'):!document.body.classList.contains('closed')))};$('#shade').onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
function calendar(){
selected=today();viewMonth=selected.slice(0,7);
main.innerHTML=`<section class="selected-day" aria-labelledby="selected-title"><div class="eyebrow">CALENDÁRIO LEGISLATIVO</div><div class="update-notice" role="note"><span class="update-dot" aria-hidden="true"></span><span><b>Atualização diária prevista por volta das 15h</b> · horário de Brasília.</span></div><div class="toolbar day-heading"><div><span id="day-tag" class="day-tag"></span><h1 id="selected-title" tabindex="-1"></h1><p id="selected-weekday" class="intro"></p></div><button id="today">Voltar para hoje</button></div><div class="filters"><label>BUSCAR PROPOSTA OU AUTOR<input id="search" placeholder="⌕  Número, ano ou nome do autor"></label><label>CASA LEGISLATIVA<select id="house"><option value="">Todas as Casas</option><option>Câmara</option><option>Senado</option></select></label><label>PROPOSTA<select id="type"><option value="">PLPs e PECs</option><option>PLP</option><option>PEC</option></select></label><label>ASSUNTO<select id="subject"><option value="">Todos os assuntos</option><option>Economia</option><option>Educação</option><option>Saúde</option><option>Instituições</option><option>Outros</option><option>Não classificado</option></select></label><label>MOVIMENTAÇÃO<select id="movement"><option value="">Todas as etapas</option><option>Apresentação</option><option>Tramitação</option><option>Votação</option><option>Reunião prevista</option></select></label></div><div id="day-content" aria-live="polite"></div></section><section class="month-panel" aria-labelledby="month-title"><div class="month-toolbar"><div><div class="eyebrow">ESCOLHA UMA DATA</div><h2 id="month-title"></h2></div><div class="month-controls"><button id="previous-month" aria-label="Mês anterior">←</button><input id="month-picker" type="month" aria-label="Escolher mês"><button id="next-month" aria-label="Próximo mês">→</button></div></div><p class="calendar-help">Clique em um dia para ver suas movimentações acima.</p><div class="weekdays" aria-hidden="true">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>'<span>'+d+'</span>').join('')}</div><div id="month-grid" class="month-grid" aria-label="Dias do mês"></div><div class="calendar-legend"><span><i class="record-dot"></i> Com registros na coleta</span><span>Sem marcador não significa ausência de atividade</span></div></section><div class="coverage"><b><i class="dot"></i> ${index.sources?.camara?.status==='not_started'?'Senado: cobertura parcial · Câmara: coleta pendente':'Câmara e Senado · cobertura parcial'}</b><span>${index.lastUpdated?'Atualização: '+new Date(index.lastUpdated).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Atualização pendente'}</span></div>`;
$('#today').onclick=()=>selectDay(today());
$('#month-picker').value=viewMonth;
$('#month-picker').onchange=()=>{if(/^\d{4}-\d{2}$/.test($('#month-picker').value)){viewMonth=$('#month-picker').value;renderMonth()}};
$('#previous-month').onclick=()=>moveMonth(-1);$('#next-month').onclick=()=>moveMonth(1);
document.querySelectorAll('.filters input,.filters select').forEach(x=>x.addEventListener('input',renderDays));
renderDays();renderMonth();
}
function selectDay(date){selected=date;viewMonth=date.slice(0,7);renderDays();renderMonth();$('#selected-title').focus({preventScroll:true});$('#selected-title').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function moveMonth(offset){const d=new Date(viewMonth+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+offset);viewMonth=d.toISOString().slice(0,7);renderMonth()}
async function renderMonth(){
const token=++gridGeneration,m=viewMonth,target=$('#month-grid');$('#calendar-error')?.remove();$('#month-title').textContent=monthName(m+'-01');$('#month-picker').value=m;
const first=new Date(m+'-01T12:00:00Z'),count=new Date(first.getUTCFullYear(),first.getUTCMonth()+1,0).getDate(),offset=first.getUTCDay();
const draw=data=>{let html=Array.from({length:offset},()=>'<span class="blank-day" aria-hidden="true"></span>').join('');for(let n=1;n<=count;n++){const date=m+'-'+String(n).padStart(2,'0'),has=data?.events?.some(e=>e.date===date);html+=`<button type="button" class="calendar-date ${date===selected?'is-selected':''} ${date===today()?'is-today':''}" data-date="${date}" aria-label="${fmt(date)}${date===today()?', hoje':''}${has?', com registros na coleta':''}" aria-pressed="${date===selected}" ${date===today()?'aria-current="date"':''}><span>${n}</span>${has?'<i class="record-dot" aria-hidden="true"></i>':''}</button>`}target.innerHTML=html;target.querySelectorAll('button').forEach(b=>b.onclick=()=>selectDay(b.dataset.date))};
draw(null);try{const data=await month(m);if(token!==gridGeneration||!document.contains(target))return;draw(data)}catch{if(token===gridGeneration)$('#calendar-error')?.remove();if(document.contains(target))target.insertAdjacentHTML('afterend','<p id="calendar-error" class="error">Não foi possível consultar os marcadores deste mês. Os dias continuam selecionáveis.</p>')}
}
function progressCard(p){const a=progress.proposals?.[p.id];if(!a)return `<section class="progress-card"><h3>Andamento atual</h3><p>Situação no último registro: ${esc(p.stage||'Não informada')}.</p><p>O órgão responsável ainda não foi consultado. <a href="${esc(p.source)}" target="_blank" rel="noopener">Ver andamento oficial ↗</a></p></section>`;return `<section class="progress-card"><h3>Andamento atual</h3>${a.error?`<p class="error">${esc(a.error)} Os dados abaixo são da última consulta disponível.</p>`:''}<p><b>Situação:</b> ${esc(a.situation||'Não informada pela fonte')}<br><b>Onde está:</b> ${esc(a.body||'Órgão não informado pela fonte')}</p>${a.awaitingRapporteur?'<p><b>Relatoria:</b> aguardando a escolha de um relator, que analisa a proposta e apresenta um parecer.</p>':a.lastRapporteur?`<p><b>Último relator informado pela Câmara:</b> ${esc(a.lastRapporteur)}. Esse registro não confirma que a proposta esteja atualmente com ele.</p>`:''}${a.lastAction?`<p><b>Última movimentação${a.actionAt?' · '+fmt(a.actionAt.slice(0,10)):''}:</b> ${esc(a.lastAction)}</p>`:''}<small>Consulta: ${a.checkedAt?new Date(a.checkedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'indisponível'} · A situação pode mudar após a consulta.</small><p><a href="${esc(a.source||p.source)}" target="_blank" rel="noopener">Conferir andamento na fonte oficial ↗</a></p></section>`}
function item(e,proposals,dayEvents=[e]){const p=proposals.find(p=>p.id===e.proposalId);if(!p)return '';const authors=p.authors||[];return `<details class="proposal-item"><summary><span class="proposal-id">${esc(p.type)} ${esc(p.number)}/${esc(p.year)} <span class="badge">${esc(p.house)}</span></span><div class="proposal-authors"><b>Autoria:</b> ${esc(authors.slice(0,2).map(a=>a.name+' · '+(a.party||'partido não informado')+'/'+(a.state||'UF não informada')).join('; ')||'Não informada')}${authors.length>2?' e mais '+(authors.length-2)+' autores':''}</div><p class="proposal-description">${esc(p.summary||'O resumo desta proposta está em preparação. Consulte o texto na fonte oficial.')}</p><small class="summary-label">${esc(p.summaryLabel||(p.aiSummary?'Resumo elaborado com auxílio de IA':'Resumo da proposta'))}</small></summary><div class="detail">${progressCard(p)}<h3>O que aconteceu neste dia</h3>${dayEvents.map(v=>`<p><b>${esc(v.kind)}</b> · ${esc(v.description)}<br>Etapa: ${esc(v.stage||'Não informada')}<br>Objeto: ${esc(v.target||'Não classificado')} · ${v.scheduled?'Reunião prevista, sem decisão confirmada':'Informe de movimentação'}</p>`).join('')}<h3>Autoria e relatoria</h3><p>${authors.map(a=>esc(`${a.name} · ${a.party||'partido não informado'}/${a.state||'UF não informada'} (${a.role})`)).join('; ')||'Autoria ainda não disponível'}</p>${p.authorshipNote?'<p>'+esc(p.authorshipNote)+'</p>':''}<p>Relator: ${esc(e.rapporteur||'Não disponível')}<br>Autor de substitutivo: ${esc(e.substituteAuthor||'Não disponível')}</p><h3>Ementa oficial</h3><p>${esc(p.officialSummary)}</p><h3>Histórico coletado</h3>${(p.history||[]).map(h=>`<p>${fmt(h.date)} · ${esc(h.description)}</p>`).join('')||'<p>Histórico ainda incompleto.</p>'}<h3>Votações</h3>${dayEvents.map(v=>`<p>Resultado: ${esc(v.vote?.result||'Resultado de votação ainda não coletado')}</p>${v.vote?.nominalOfficial?['favor','contra','abstencao'].map(k=>`<p>${k}: ${(v.vote[k]||[]).map(a=>esc(a.name+' · '+a.party+'/'+a.state)).join(', ')||'Nenhum voto nesta categoria no registro oficial'}</p>`).join(''):'<p>Sem registro individual de votos disponível</p>'}`).join('')}${(e.conflict||p.conflict)?'<p class="error">Divergência de vínculo partidário entre campos da fonte: confirmação pendente. O resumo de autoria original foi preservado.</p>':''}<a href="${esc(p.source)}" target="_blank" rel="noopener">Consultar fonte oficial ↗</a><p>Atualizado em: ${e.collectedAt?new Date(e.collectedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Não informado'}</p></div></details>`}
async function renderDays(){
const token=++generation,target=$('#day-content'),date=selected;
$('#day-tag').textContent=date===today()?'HOJE':'DIA SELECIONADO';
$('#selected-title').textContent=new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});
$('#selected-weekday').textContent=new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long'});
target.innerHTML='<p>Carregando movimentações deste dia…</p>';
try{const data=await month(date.slice(0,7));if(token!==generation||!document.contains(target))return;
const c=data?.days?.[date],raw=data?.events?.filter(e=>e.date===date)||[],events=raw.filter(e=>{const p=data.proposals.find(p=>p.id===e.proposalId);return p&&(!$('#house').value||p.house===$('#house').value)&&(!$('#type').value||p.type===$('#type').value)&&(!$('#subject').value||(p.subject||'Não classificado')===$('#subject').value)&&(!$('#movement').value||e.kind===$('#movement').value)&&JSON.stringify([p.number,p.year,p.authors,p.type]).toLowerCase().includes($('#search').value.toLowerCase())});
const complete=c?.status==='complete';
target.innerHTML=`<div class="day-results-heading"><h2>Movimentações do dia</h2><span>${events.length?events.length+' registro'+(events.length===1?'':'s'):'Cobertura '+(complete?'consultada':'pendente')}</span></div>${events.length?'<p class="partial-day">Cobertura parcial · Consulte a Casa e a fonte oficial em cada proposta</p>'+events.filter((e,i,a)=>a.findIndex(v=>v.proposalId===e.proposalId)===i).map(e=>item(e,data.proposals,events.filter(v=>v.proposalId===e.proposalId))).join(''):`<div class="empty"><span class="symbol">◷</span><div><strong>${raw.length?'Nenhum resultado para os filtros':complete?'Sem movimentações confirmadas':c?.status==='partial'?'Coleta incompleta':'Este dia ainda não foi consultado'}</strong><p>${raw.length?'Tente ajustar a busca ou os filtros.':complete?'As fontes foram consultadas para ambas as Casas.':'A ausência de registros não significa ausência de atividade legislativa.'}</p></div></div>`}`;
}catch{if(token===generation&&document.contains(target)){target.innerHTML='<div class="note error">Falha ao carregar este dia. <button id="retry">Tentar novamente</button></div>';$('#retry').onclick=renderDays}}
}
async function ranking(){
const initial=index.sources?.camara?.status==='not_started'?'Senado':'Câmara',from=index.availableRecordPeriod?.from||today(),to=today();
main.innerHTML=heading('AUTORIA EM PERSPECTIVA','Deputados e senadores','Conheça os autores das propostas, veja suas fotos oficiais e consulte os textos apresentados.')+`<div class="note">O ranking considera apenas PLPs e PECs e o período efetivamente coletado. Quantidade de propostas não é medida de qualidade ou produtividade parlamentar.</div><section class="panel"><div class="rank-filters"><label>PARLAMENTARES<select id="chamber"><option value="Câmara">Deputados federais</option><option value="Senado">Senadores</option></select></label><label>DE<input type="date" id="from" value="${from}"></label><label>ATÉ<input type="date" id="to" value="${to}"></label><label>TIPO<select id="rt"><option value="">PLP e PEC</option><option>PLP</option><option>PEC</option></select></label><label>AUTORIA<select id="role"></select></label><label>NOME<input id="name" placeholder="Buscar parlamentar"></label></div></section><div id="ranks" aria-live="polite"></div><details><summary>Como a contagem é calculada</summary><div class="detail">Cada proposta é contada uma única vez pelo identificador oficial, conforme a data de apresentação. Autoria principal e coautoria da Câmara são separadas. No Senado, a ordem das assinaturas não comprova autoria principal: a categoria é autoria oficial registrada. Movimentações, pareceres e relatorias não são novas propostas. Partido e estado correspondem ao registro da autoria e podem variar no período. Fotos são retratos atuais das fontes oficiais e não comprovam o vínculo partidário na data do registro. Sem foto disponível, exibimos as iniciais do nome. Empates recebem a mesma posição e autores sem identificador oficial ficam fora da contagem.</div></details>`;
$('#chamber').value=initial;const setRoles=()=>{$('#role').innerHTML=$('#chamber').value==='Senado'?'<option value="autoria conjunta">Autoria oficial registrada</option>':'<option value="principal">Principal</option><option value="coautoria">Coautoria</option>'};setRoles();
document.querySelectorAll('.rank-filters input,.rank-filters select').forEach(x=>x.oninput=renderRank);$('#chamber').onchange=()=>{setRoles();renderRank()};renderRank();
}
async function renderRank(){const token=++generation,target=$('#ranks'),from=$('#from').value,to=$('#to').value,house=$('#chamber').value;
if(!from||!to||from>to){target.innerHTML='<div class="note">Escolha um período válido.</div>';return}target.innerHTML='<p>Consultando arquivos do período…</p>';
try{const data=await Promise.all(index.months.filter(m=>m.month>=from.slice(0,7)&&m.month<=to.slice(0,7)).map(m=>month(m.month)));if(token!==generation||!document.contains(target))return;
const unique=new Map(data.flatMap(d=>d.proposals).map(p=>[p.id,p])),counts=new Map;
for(const p of unique.values()){if(p.house!==house||p.presentedAt<from||p.presentedAt>to||($('#rt').value&&p.type!==$('#rt').value))continue;
for(const a of p.authors||[]){if(a.role!==$('#role').value||a.office!==(house==='Senado'?'senador':'deputado federal')||!a.id)continue;let row=counts.get(a.id)||{...a,parties:[],states:[],proposals:[]};if(!row.parties.includes(a.party))row.parties.push(a.party);if(!row.states.includes(a.state))row.states.push(a.state);if(!row.proposals.some(x=>x.id===p.id))row.proposals.push(p);counts.set(a.id,row)}}
const rows=[...counts.values()].sort((a,b)=>b.proposals.length-a.proposals.length||a.name.localeCompare(b.name));let previous=-1,rank=0;rows.forEach((a,i)=>{if(a.proposals.length!==previous)rank=i+1;previous=a.proposals.length;a.rank=rank});
const found=rows.filter(a=>a.name.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes($('#name').value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'')));
const notice='<div class="note">'+(house==='Senado'?'Exibindo senadores com propostas no período. ':'Exibindo deputados federais com propostas no período. ')+'Cobertura parcial: esta contagem não representa todo o histórico.</div>';
if(!rows.length){target.innerHTML=notice+(house==='Câmara'&&index.sources?.camara?.status==='not_started'?'<div class="panel"><h2>Os dados dos deputados ainda estão em coleta.</h2><p>Os nomes não foram removidos: o ranking da Câmara ainda não tem propostas importadas. A ausência de dados não equivale a zero propostas.</p><button id="see-senators">Ver senadores disponíveis</button></div>':'<div class="panel"><h2>Não há contagens disponíveis para este período.</h2><p>Ajuste o período ou o tipo de proposta. Dados ausentes não equivalem a zero propostas.</p></div>');$('#see-senators')?.addEventListener('click',()=>{$('#chamber').value='Senado';$('#chamber').onchange()});return}
target.innerHTML=notice+(!found.length?'<div class="panel">Nenhum nome corresponde à busca. Tente outro nome ou remova o filtro.</div>':found.map(a=>`<details class="politician-row"><summary><span class="rank-number">${a.rank}</span>${portrait(a)}<span class="politician-identity"><strong>${esc(a.name)}</strong><span>${esc(a.parties.filter(Boolean).join(' / ')||'Partido não informado')} · ${esc(a.states.filter(Boolean).join(' / ')||'UF não informada')}</span></span><span class="politician-count"><b>${a.proposals.length}</b><span>${a.proposals.filter(p=>p.type==='PLP').length} PLPs · ${a.proposals.filter(p=>p.type==='PEC').length} PECs</span></span><span class="row-chevron" aria-hidden="true">⌄</span></summary><div class="detail"><h3>Propostas que compõem a contagem</h3>${a.proposals.map(p=>`<p><a href="${esc(p.source)}" target="_blank" rel="noopener">${p.type} ${p.number}/${p.year} ↗</a> · ${esc(p.summary||p.officialSummary)}<br>${esc(p.authors.find(x=>x.id===a.id)?.party||'Partido não informado')}/${esc(p.authors.find(x=>x.id===a.id)?.state||'UF não informada')}</p>${progressCard(p)}`).join('')}</div></details>`).join(''));bindPortraitErrors();
}catch{if(token===generation&&document.contains(target))target.innerHTML='<div class="note error">Não foi possível consultar o ranking. Recarregue a página para tentar novamente.</div>'}}
async function support(){main.innerHTML=heading('INFORMAÇÃO PÚBLICA, APOIO COLETIVO','Ajude a manter o olhar atento.','O Vigia Congresso existe para aproximar as pessoas das decisões do Legislativo.')+`<div class="panel support"><div class="support-icon">♡</div><h2>Seu apoio faz parte dessa história.</h2><p>Doações voluntárias ajudam a manter o projeto, a coleta diária, a verificação das fontes e a disponibilização gratuita das informações.</p><div id="donate" class="note">As doações estarão disponíveis em breve.</div><p style="font-size:11px">Apoiar é uma escolha. O acesso à informação continua livre para todos.</p></div>`;try{const c=await json('data/support.json');if(c.pixKey&&c.recipient){$('#donate').innerHTML=`<p>Destinatário: ${esc(c.recipient)}</p><code>${esc(c.pixKey)}</code> <button id="copy">Copiar chave Pix</button><span id="copied" role="status"></span>${c.qrImage?`<p><img style="max-width:220px" src="${esc(c.qrImage)}" alt="QR Code Pix do destinatário configurado"></p>`:''}`;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(c.pixKey);$('#copied').textContent=' Chave copiada.'}catch{$('#copied').textContent=' Selecione e copie a chave acima.'}}}}catch{}}
function methodology(){main.innerHTML=heading('TRANSPARÊNCIA POR PRINCÍPIO','Fontes e metodologia','A confiança começa por mostrar o que sabemos — e o que ainda falta consultar.')+`<section class="panel"><h2>Dados oficiais, contexto preservado</h2><p>As referências são os <a href="https://dadosabertos.camara.leg.br/swagger/api.html">Dados Abertos da Câmara</a> e os <a href="https://www12.senado.leg.br/dados-abertos">Dados Abertos do Senado</a>. O site não representa nenhuma das Casas.</p><p>O calendário já inclui informes legislativos oficiais do Senado em novembro de 2026, referentes a PLPs e PECs identificadas em 2026. A cobertura é parcial: propostas de outros anos, resultados e votos nominais ainda não têm coleta completa. A Câmara já inclui PLPs e PECs com apresentação ou tramitação no período consultado, inclusive propostas de anos anteriores que tiveram movimentação recente. A cobertura das duas Casas ainda é parcial. Dezembro de 2026 e janeiro de 2027 são arquivos preparados, sem registros futuros inventados.</p><p>Um dia só pode ser marcado como completo após consulta bem-sucedida de todas as fontes necessárias. Falhas, paginação incompleta e dados não classificados mantêm a cobertura parcial. Publicações atrasadas exigem revisão retroativa.</p><p>Presença não é voto. Sem registro nominal oficial, não há lista individual nem inferência de votos. Votações de texto principal, emenda, parecer e requerimento são objetos distintos. Reuniões previstas não são decisões realizadas.</p><p>Resumos de IA, quando usados, recebem identificação. Divergências ficam pendentes de confirmação. As informações podem ser corrigidas na fonte oficial.</p><a href="data/index.json">Consultar índice de cobertura JSON ↗</a></section>`}
async function route(){generation++;closeMenu();const page=location.hash.slice(1)||'calendario';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));if(!index){try{index=await json('data/index.json')}catch{main.innerHTML='<div class="panel">Não foi possível carregar o índice. <button onclick="location.reload()">Tentar novamente</button></div>';return}}if(!progressLoaded){try{progress=await json('data/progress.json')}catch{}progressLoaded=true}if(!portraitsLoaded){try{portraits=await json('data/portraits.json')}catch{}portraitsLoaded=true}({calendario:calendar,ranking,apoie:support,metodologia:methodology}[page]||calendar)();scrollTo(0,0)}addEventListener('hashchange',route);route();
